func newTestPrivacyBlur(t *testing.T) *PrivacyBlur {
	t.Helper()
	pb, err := NewPrivacyBlur(PrivacyBlurConfig{
		Classifiers: []ClassifierConfig{
			{
				Name:         "face",
				XML:          cascadedata.FaceFrontalDefault,
				ScaleFactor:  1.1,
				MinNeighbors: 3,
				MinSize:      image.Pt(30, 30),
			},
		},
		BlurRadius: 10,
	})
	require.NoError(t, err)
	return pb
}

func newTestVideoFrame(t *testing.T, w, h int) *astiav.Frame {
	t.Helper()
	f := astiav.AllocFrame()
	f.SetWidth(w)
	f.SetHeight(h)
	f.SetPixelFormat(astiav.PixelFormatYuv420P)
	require.NoError(t, f.AllocBuffer(32))
	return f
}

func newTestVideoInput(t *testing.T, w, h int) packetorframe.InputUnion {
	t.Helper()
	f := newTestVideoFrame(t, w, h)
	codecParams := astiav.AllocCodecParameters()
	codecParams.SetMediaType(astiav.MediaTypeVideo)
	codecParams.SetWidth(w)
	codecParams.SetHeight(h)
	codecParams.SetPixelFormat(astiav.PixelFormatYuv420P)
	return packetorframe.InputUnion{
		Frame: &frame.Input{
			Frame: f,
			StreamInfo: &frame.StreamInfo{
				StreamIndex:     0,
				CodecParameters: codecParams,
			},
		},
	}
}

func TestPrivacyBlur_Passthrough(t *testing.T) {
	pb := newTestPrivacyBlur(t)
	defer pb.Close(context.Background())

	enabled := &atomic.Bool{}
	enabled.Store(false)
	pb.Enabled = enabled

	ctx := context.Background()
	input := newTestVideoInput(t, 320, 240)
	defer input.Frame.Frame.Free()
	defer input.Frame.CodecParameters.Free()
	outputCh := make(chan packetorframe.OutputUnion, 1)

	err := pb.SendInput(ctx, input, outputCh)
	require.NoError(t, err)
	require.Len(t, outputCh, 1)

	out := <-outputCh
	require.NotNil(t, out.Frame)
}

func TestPrivacyBlur_EnabledNil(t *testing.T) {
	pb := newTestPrivacyBlur(t)
	defer pb.Close(context.Background())
	// Enabled is nil = always on (should not panic).

	ctx := context.Background()
	input := newTestVideoInput(t, 320, 240)
	defer input.Frame.Frame.Free()
	defer input.Frame.CodecParameters.Free()
	outputCh := make(chan packetorframe.OutputUnion, 1)

	err := pb.SendInput(ctx, input, outputCh)
	require.NoError(t, err)
	require.Len(t, outputCh, 1)

	out := <-outputCh
	require.NotNil(t, out.Frame)
	testifyassert.Equal(t, 320, out.Frame.Width())
	testifyassert.Equal(t, 240, out.Frame.Height())
}

