	pb.Enabled = enabled

	ctx := context.Background()

	// Frame 1: enabled.
	input1 := newTestVideoInput(t, 320, 240)
	defer input1.Frame.Frame.Free()
	defer input1.Frame.CodecParameters.Free()
	outputCh := make(chan packetorframe.OutputUnion, 1)
	err := pb.SendInput(ctx, input1, outputCh)
	require.NoError(t, err)
	require.Len(t, outputCh, 1)
	<-outputCh

	// Disable.
	enabled.Store(false)

	// Frame 2: disabled (passthrough).
